      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-plugin\",\n  \"version\": \"2.4.0\",\n  \"description\": \"A community plugin marketplace for DeepSeek Harness, built to the official plugin spec — browse, search and install 6000+ hand-verified npm plugins out of 23000+ indexed, without leaving the app. · DeepSeek Harness 社区插件市场（遵循官方开发规范）：收录 23000+ 社区插件，其中 6000+ 已发布 npm 包、可一键安装，每日更新。\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/dshplugin/dsh-plugin-hub.git\"\n  },\n  \"homepage\": \"https://dsh-plugin.org\",\n  \"bugs\": {\n    \"url\": \"https://github.com/dshplugin/dsh-plugin-hub/issues\"\n  },\n  \"author\": \"DSH Plugin Hub contributors\",\n  \"funding\": {\n    \"type\": \"custom\",\n    \"url\": \"https://dsh-plugin.org\"\n  },\n  \"engines\": {\n    \"node\": \">=22.6\"\n  },\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"plugin-marketplace\",\n    \"plugin-hub\",\n    \"community-plugins\",\n    \"plugins\",\n    \"marketplace\",\n    \"ai\",\n    \"agent\",\n    \"cli\",\n    \"typescript\",\n    \"open-source\"\n  ],\n  \"scripts\": {\n    \"build\": \"npm run build:server && npm run build:client\",\n    \"build:server\": \"rm -rf lib && tsc -p tsconfig.server.json\",\n    \"build:client\": \"tsdown && node scripts/tools/normalize-client-banner.mjs\",\n    \"readme:stats\": \"node scripts/tools/sync-readme-stats.mjs\",\n    \"reload\": \"bash scripts/run/restart-dev.sh\",\n    \"dev\": \"bash scripts/run/restart-dev.sh\",\n    \"test\": \"node --test\",\n    \"test:watch\": \"node --test --watch\",\n    \"typecheck\": \"npm run typecheck:client && npm run typecheck:server && npm run typecheck:test\",\n    \"typecheck:client\": \"tsc -p tsconfig.client.json --noEmit\",\n    \"typecheck:server\": \"tsc -p tsconfig.server.json --noEmit\",\n    \"typecheck:test\": \"tsc -p tsconfig.test.json --noEmit\",\n    \"check\": \"npm run typecheck && npm run test && npm run build\",\n    \"verify:release\": \"node scripts/tools/verify-release.mjs\",\n    \"prepublishOnly\": \"npm run verify:release\",\n    \"prepack\": \"npm run build\"\n  },\n  \"dependencies\": {},\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./client/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"client\",\n    \"cordis.patch.yml\",\n    \"LICENSE\"\n  ],\n  \"devDependencies\": {\n    \"@types/node\": \"24.13.3\",\n    \"@types/react\": \"18.3.31\",\n    \"lightningcss\": \"1.33.0\",\n    \"react\": \"18.3.1\",\n    \"tsdown\": \"0.22.14\",\n    \"typescript\": \"7.0.2\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    }\n  }\n}\n"
