      "path": "cordis.patch.yml",
      "content": "# dsh bundle patch: inserts the DSH Plugin section into a profile's layer stack.\n- insert:\n    - id: dsh-plugin\n      name: 'dsh-plugin'\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * dsh-plugin 宿主入口：宿主 webServer 服务就绪后挂载插件中心的 HTTP 路由。\n * 浏览器 bundle（src/client）通过这些同源路由在应用内执行真正的安装。\n */\nimport { readProfileArg } from './services/install/install.js';\nimport { mountPluginHubRoutes } from './http/routes.js';\nexport const name = 'dsh-plugin';\n/**\n * webServer 服务就绪后挂载插件中心路由。\n * @param ctx - cordis 宿主上下文。\n * @param config - 可选的 profile 覆盖。\n */\nexport function apply(ctx, config = {}) {\n    const profile = config.profile ?? readProfileArg('web');\n    ctx.inject(['webServer'], (host) => {\n        host.effect(() => mountPluginHubRoutes(host.webServer, profile, host.loader), 'dsh-plugin: http routes');\n    });\n}\n"
    },
    {
      "path": "tsdown.config.ts",
      "content": "/**\n * Browser client bundle for the dsh-plugin package, mirroring the\n * DeepSeek Harness client preset for an external package: a\n * closure-factory artifact that calls window.__ModuleLoader__.load({ id,\n * factory }) and resolves externals through the injected require (loader\n * module table). CSS Modules compile via lightningcss inside the bundle;\n * importing `x.module.css` yields the hashed class map and the css text\n * auto-injects a <style data-plugin> tag at factory execution.\n *\n * scripts/tools/normalize-client-banner.mjs asserts the emitted client/client.js\n * starts with the exact `window.__ModuleLoader__.load({ id: \"…` prefix.\n */\nimport { readFile } from 'node:fs/promises'\nimport { createRequire } from 'node:module'\nimport { basename, dirname, resolve as resolvePath } from 'node:path'\nimport { defineConfig } from 'tsdown'\nimport { transform } from 'lightningcss'\n\n// 配置加载器是 ESM，JSON 只能经 require 读取（Node 原生支持）\nconst pkg = createRequire(import.meta.url)('./package.json') as { version: string }\n\nconst id = 'dsh-plugin'\n\n/** Externals resolved from the loader module table at runtime. */\nconst CLIENT_EXTERNALS = ['react', 'react/jsx-runtime']\n\n/** Virtual-id wrapper keeping module CSS away from tsdown's own css pipeline. */\nconst CSS_VIRTUAL_PREFIX = '\\0dsh-css:'\nconst CSS_VIRTUAL_SUFFIX = '.mjs'\n\nexport default defineConfig({\n  entry: { client: 'src/client/index.tsx' },\n  outDir: 'client',\n  format: 'cjs',\n  platform: 'browser',\n  target: 'es2022',\n  dts: false,\n  sourcemap: true,\n  clean: false,\n  external: [...CLIENT_EXTERNALS],\n  noExternal: (source: string) => (CLIENT_EXTERNALS.includes(source) ? undefined : true),\n  define: {\n    'process.env.NODE_ENV': JSON.stringify('production'),\n    'import.meta.env.MODE': JSON.stringify('production'),\n    'import.meta.env': JSON.stringify({ MODE: 'production' }),\n    // 头部标题展示的插件版本号：构建时从 package.json 注入，避免客户端重复维护版本\n    __PLUGIN_VERSION__: JSON.stringify(pkg.version),\n  },\n  plugins: [{\n    name: 'dsh-css-modules-inline',\n    resolveId(source: string, importer: string | undefined) {\n      if (!source.endsWith('.module.css')) return null\n      const abs = importer !== undefined ? resolvePath(dirname(importer), source) : source\n      return CSS_VIRTUAL_PREFIX + abs + CSS_VIRTUAL_SUFFIX\n    },\n    async load(this: { addWatchFile(file: string): void }, virtualId: string) {\n      if (!virtualId.startsWith(CSS_VIRTUAL_PREFIX)) return null\n      const fileId = virtualId.slice(CSS_VIRTUAL_PREFIX.length, -CSS_VIRTUAL_SUFFIX.length)\n      this.addWatchFile(fileId)\n      const source = await readFile(fileId)\n      const { code, exports: cssExports } = transform({\n        filename: fileId,\n        code: source,\n        cssModules: { pattern: '[hash]_[local]' },\n        minify: true,\n        targets: { chrome: 90 << 16, firefox: 100 << 16, safari: 13 << 16, edge: 90 << 16 },\n      })\n      const classMap: Record<string, string> = {}\n      for (const [local, exp] of Object.entries(cssExports ?? {})) classMap[local] = exp.name\n      return [\n        `const css = ${JSON.stringify(code.toString())};`,\n        `const tagId = ${JSON.stringify(`${id}/${basename(fileId)}`)};`,\n        'if (typeof document !== \\'undefined\\' && document.querySelector(\\'style[data-plugin-css=\\' + JSON.stringify(tagId) + \\']\\') === null) {',\n        '  const tag = document.createElement(\\'style\\');',\n        `  tag.dataset.plugin = ${JSON.stringify(id)};`,\n        '  tag.dataset.pluginCss = tagId;',\n        '  tag.textContent = css;',\n        '  document.head.appendChild(tag);',\n        '}',\n        // 登记到全局清单：宿主重启后页面不刷新、factory 不重跑时，\n        // 客户端挂载时据此比对 DOM 并补注入缺失的样式（自愈）。\n        `const cssRegistry = (globalThis.__DSH_PLUGIN_CSS__ ??= []);`,\n        'if (!cssRegistry.some(e => e.tagId === tagId)) cssRegistry.push({ tagId, css });',\n        `export default ${JSON.stringify(classMap)};`,\n      ].join('\\n')\n    },\n  }],\n  outputOptions: {\n    entryFileNames: 'client.js',\n    banner: `window.__ModuleLoader__.load({ id: ${JSON.stringify(id)}, factory: (require) => {`,\n    footer: 'return module.exports; } });',\n    intro: 'var module = { exports: {} }; var exports = module.exports;',\n  },\n})\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * dsh-plugin 客户端入口：通过模块加载器 bundle（见 tsdown.config.ts）把插件中心接入宿主设置。\n * 全部 UI 逻辑都在 PluginHubSection；本文件只做 cordis apply 接线。\n */\nimport { createElement as h } from 'react'\nimport type { HubClientContext } from './types.ts'\nimport { en, pt, zh } from './locales.ts'\nimport { PT_LANGUAGE } from './logic/locale-key.ts'\nimport { PluginHubSection } from './components/PluginHubSection.tsx'\nimport './styles/tokens.module.css'\n\nconst NS = 'dsh-plugin'\n\nexport const name = NS\nexport const inject = ['slots', 'locale']\n\nexport function apply(ctx: HubClientContext): void {\n  // 宿主内置语言只有 zh / en；pt 必须先注册进语言目录，否则 setLocale('pt') 会抛\n  // 「locale \"pt\" is not registered」。别的语言包可能已经注册过 pt（含 pt-BR 这类），\n  // 重复注册会抛错 —— 那种情况沿用已有定义即可，不能因此让整个插件加载失败。\n  ctx.effect(() => {\n    try {\n      return ctx.locale.addLanguage(PT_LANGUAGE)\n    } catch {\n      return undefined\n    }\n  }, `${NS}: pt language`)\n  ctx.effect(() => ctx.locale.register(NS, { zh, en, pt }), `${NS}: dictionaries`)\n  const t = ctx.locale.bind(NS)\n  ctx.slots.inject('settings.section', () => ctx.slots.register({\n    name: 'settings.section',\n    id: NS,\n    order: 60,\n    label: () => t('nav'),\n    locale: NS,\n    inject: () => ({ t, locale: ctx.locale }),\n  }, () => h(PluginHubSection, { t, locale: ctx.locale })))\n}\n"
    },
    {
      "path": "src/server/http/catalog.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 目录代理路由：目录/统计载荷的服务端缓存，以及与安装/任务模块共享的 profile 级已装包读取。\n */\nimport { mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { dirname, join } from 'node:path'\nimport { githubRepoOf } from '../services/install/install.ts'\nimport { loadSettings } from '../services/settings.ts'\nimport { fetchViaCurl, systemProxy } from '../services/probe.ts'\nimport { CATALOG_CACHE_TTL_MS, requireMethod, sendJson, type WebRoute, type WebServerService } from './shared.ts'\n\n/** 磁盘缓存内容：原始响应字符串 + 写入时间戳（TTL 判定用）。 */\ninterface CatalogCacheEntry {\n  at: number\n  body: string\n}\n\nfunction catalogCacheFile(profile: string, key: string): string {\n  return join(profileDirectory(profile), 'cache', `catalog-${key}.json`)\n}\n\n/** 目录拉取超时：目录 JSON 约 3.6MB，20s 在弱网/代理链路上不够用；\n *  客户端会在超时后重试，重试必须共享同一次拉取（见 fetchCatalogOnce）。 */\nconst CATALOG_FETCH_TIMEOUT_MS = 60_000\n\n/** 并发拉取去重：客户端超时重试会并发打进来，共享同一次 curl，\n *  避免多份 3.6MB 下载互相抢带宽、越重试越慢。 */\nconst inflightCatalog = new Map<string, ReturnType<typeof fetchViaCurl>>()\n\nfunction fetchCatalogOnce(target: string, proxy: string): ReturnType<typeof fetchViaCurl> {\n  const key = `${target}\\n${proxy}`\n  const running = inflightCatalog.get(key)\n  if (running !== undefined) return running\n  const task = fetchViaCurl(target, proxy, CATALOG_FETCH_TIMEOUT_MS)\n    .finally(() => { inflightCatalog.delete(key) })\n  inflightCatalog.set(key, task)\n  return task\n}\n\n/** 读缓存：文件存在、JSON 合法、未超过 maxAgeMs → 返回原始响应字符串；否则 null（视为 miss）。\n *  maxAgeMs 传 Infinity 即「任意年龄的缓存」，供实时拉取失败时使用。 */\nfunction readCatalogCache(file: string, maxAgeMs: number): string | null {\n  try {\n    const entry = JSON.parse(readFileSync(file, 'utf8')) as CatalogCacheEntry\n    if (entry && typeof entry.at === 'number' && typeof entry.body === 'string'\n      && Date.now() - entry.at < maxAgeMs) {\n      return entry.body\n    }\n  } catch {\n    // 文件缺失 / 解析失败 / 字段不完整 → miss，重新拉取覆盖写盘\n  }\n  return null\n}\n\n/** 写缓存：目录不存在则创建；写失败直接忽略（缓存只是加速，不影响功能）。 */\nfunction writeCatalogCache(file: string, body: string): void {\n  try {\n    mkdirSync(dirname(file), { recursive: true })\n    writeFileSync(file, JSON.stringify({ at: Date.now(), body } satisfies CatalogCacheEntry))\n  } catch {\n    // 磁盘只读/无权限等极端情况：忽略，继续走直连\n  }\n}\n\nexport function profileDirectory(profile: string): string {\n  return join(process.env.DSH_HOME ?? join(homedir(), '.dsh'), 'profiles', profile)\n}\n\n/** 读取安装进某 profile 的非官方依赖。 */\nexport function readInstalled(profile: string): Record<string, string> {\n  try {\n    const manifest = JSON.parse(readFileSync(join(profileDirectory(profile), 'package.json'), 'utf8')) as {\n      dependencies?: Record<string, string>\n    }\n    return Object.fromEntries(\n      Object.entries(manifest.dependencies ?? {}).filter(([name]) => !name.startsWith('@deepseek-ai/')),\n    )\n  } catch {\n    return {}\n  }\n}\n\n/** 读已装依赖实际落在磁盘上的仓库身份（`owner/repo`）：解析 node_modules/<name>/package.json\n *  的 repository 字段。已装 spec 可能是纯版本号（丢了仓库身份），但真实包元数据仍指向来源仓库，\n *  据此可区分「同名依赖其实是同一仓库的残留（应转 update）」还是「跨仓库包名冲突（应报错）」。\n *  读不到 / 解析不出返回 null（交给调用方按冲突处理）。 */\nexport function installedRepoOf(profile: string, name: string): string | null {\n  try {\n    const pkg = JSON.parse(readFileSync(join(profileDirectory(profile), 'node_modules', name, 'package.json'), 'utf8')) as {\n      repository?: string | { url?: string }\n    }\n    const repo = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url\n    return repo ? githubRepoOf(repo) : null\n  } catch {\n    return null\n  }\n}\n\nexport function registerCatalogRoutes(webServer: WebServerService, profile: string): WebRoute[] {\n  return [\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/catalog',\n      handler: async (request, response) => {\n        if (!requireMethod(request, response, 'GET')) return\n        // 目录/统计数据服务端代理：浏览器不直连 dsh-plugin.org，统一经此路由\n        // 转发（curl 子进程注入代理 env），与 npm / git 安装通道走同一代理规则，\n        // 「npm / git / 目录数据请求统一走该代理」的设置文案因此真实生效。\n        const url = new URL(request.url ?? '/', 'http://localhost')\n        const settings = loadSettings(profile)\n        // 代理优先级与安装/诊断一致：设置里的代理 → 系统代理 → 环境变量 → 直连\n        const proxy = settings.proxy !== ''\n          ? settings.proxy\n          : (systemProxy() ?? process.env.HTTPS_PROXY ?? process.env.https_proxy ?? '')\n        const isStats = url.searchParams.get('stats') === '1'\n        // 目录语言：只有中文目录和英文目录两份。除 zh 以外的界面语言（en、pt…）\n        // 都取英文目录，避免非中文用户拿到中文插件描述。\n        const lang = url.searchParams.get('lang') === 'zh' ? 'zh' : 'en'\n        const target = isStats\n          ? 'https://api.dsh-plugin.org/stats.json'\n          : `https://api.dsh-plugin.org/plugins.${lang}.json`\n        // 1 小时本地缓存：命中直接返回（跨重启生效，插件市场秒开），未命中才走 curl 拉远程。\n        // refresh=1 跳过 TTL 缓存直接回源（「强制刷新」用）；成功后照样覆盖缓存，\n        // 失败仍回退旧缓存，所以强制刷新不会把可用的旧数据弄丢。\n        const cacheFile = catalogCacheFile(profile, isStats ? 'stats' : `plugins-${lang}`)\n        const forceRefresh = url.searchParams.get('refresh') === '1'\n        const cached = forceRefresh ? null : readCatalogCache(cacheFile, CATALOG_CACHE_TTL_MS)\n        if (cached !== null) {\n          try {\n            sendJson(response, 200, JSON.parse(cached))\n            return\n          } catch {\n            // 缓存正文损坏：忽略，走重新拉取并覆盖写盘\n          }\n        }\n        const r = await fetchCatalogOnce(target, proxy)\n        if (!r.ok || r.body === '') {\n          // 实时拉取失败：退回任意年龄的本地缓存（上次成功数据），\n          // 避免证书吊销受阻 / 网络抖动时整个插件市场打不开 —— 数据可能过期，但好过空白。\n          const stale = readCatalogCache(cacheFile, Number.POSITIVE_INFINITY)\n          if (stale !== null) {\n            try {\n              sendJson(response, 200, JSON.parse(stale))\n              return\n            } catch {\n              // 备用缓存也损坏：落到下面的 502\n            }\n          }\n          // 带上 curl 退出码与 stderr 末行：只回 error 字段时，用户贴出来的响应里\n          // 没有任何可诊断信息\n          sendJson(response, 502, { error: 'catalog fetch failed', detail: r.detail })\n          return\n        }\n        try {\n          sendJson(response, 200, JSON.parse(r.body))\n          writeCatalogCache(cacheFile, r.body)\n        } catch {\n          sendJson(response, 502, { error: 'catalog fetch returned invalid JSON' })\n        }\n      },\n    },\n  ]\n}\n"
    },
    {
      "path": "src/server/http/install.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 安装/卸载路由：校验目标后 spawn 官方 dsh CLI（见 services/install/install.ts），\n * 并回传捕获的结果。自定义安装只接受 npm 包名。\n */\nimport { githubRepoOf, globalNpmPackagesOf, hasQueuedTarget, installTargetOf, startPluginMutation, validPackageName, type LoaderHandle } from '../services/install/install.ts'\nimport { recordResolvedNpmPackage } from '../services/profile/installed-versions.ts'\nimport { isDshNpmPackageForRepo } from '../services/install/npm-resolve.ts'\nimport { probeUrl, systemProxy } from '../services/probe.ts'\nimport { loadSettings, type HubSettings } from '../services/settings.ts'\nimport { registryCandidates, registryHost, userNpmRegistry } from '../services/install/registry-fallback.ts'\nimport { lookupReleaseAge } from '../services/npm-release-age.ts'\nimport { profileDirectory } from '../services/profile/profile.ts'\nimport { readInstalled } from './catalog.ts'\nimport { COMMAND_TIMEOUT_MS, readJsonBody, requireTrustedPost, sendJson, type WebRoute, type WebServerService } from './shared.ts'\n\n/** 安装/卸载 CLI 的子进程环境：原样传递宿主环境并注入 HTTP(S) 代理，\n *  代理来源与诊断一致（设置代理 → 系统代理 → 宿主 env）；registry 由任务队列按候选源逐次注入。 */\nfunction mutationEnv(settings: HubSettings): NodeJS.ProcessEnv {\n  const env: NodeJS.ProcessEnv = { ...process.env, CI: 'true' }\n  const proxy = settings.proxy !== '' ? settings.proxy : (systemProxy() ?? '')\n  if (proxy !== '') {\n    env.HTTP_PROXY = proxy\n    env.HTTPS_PROXY = proxy\n    env.http_proxy = proxy\n    env.https_proxy = proxy\n  }\n  return env\n}\n\nexport function registerInstallRoutes(webServer: WebServerService, profile: string, loader: LoaderHandle | undefined): WebRoute[] {\n  return [\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/install',\n      handler: async (request, response) => {\n        if (!requireTrustedPost(request, response)) return\n        // 任务自动入队：即使已有插件操作在跑也接受请求（FIFO 串行执行），不做 409 拒绝\n        try {\n          const body = await readJsonBody(request)\n          // mode: 'update' = 已安装目标的覆盖更新（放行 add，pnpm 对已存在依赖原位覆盖重装）。\n          let mode = body !== null && typeof body === 'object' && (body as { mode?: unknown }).mode === 'update'\n            ? 'update'\n            : 'install'\n          // installTargetOf 把完整 DSH 命令剥成裸目标；自定义目标只接受 npm 包名，语法判定交给 validPackageName。\n          const rawRepo = typeof body === 'object' && body !== null && typeof (body as { repo?: unknown }).repo === 'string'\n            ? installTargetOf((body as { repo: string }).repo)\n            : ''\n          // 展示用仓库名（owner/repo）：npm 安装时 body.repo 是包名，display 供待重启行 / 任务恢复展示仓库名。\n          const displayRepo = typeof body === 'object' && body !== null && typeof (body as { display?: unknown }).display === 'string'\n            ? (body as { display: string }).display.trim()\n            : rawRepo\n          // 请求来源：目录插件安装（catalog）走目录白名单；命令行安装（custom）受安全开关控制\n          const source = typeof body === 'object' && body !== null && typeof (body as { source?: unknown }).source === 'string'\n            ? (body as { source: string }).source\n            : ''\n          // 自定义安装入口渠道（仅 NPM 包）：日志/报错据此溯源发起入口。\n          const installChannel = (() => {\n            const raw = body !== null && typeof body === 'object' ? (body as { installChannel?: unknown }).installChannel : undefined\n            return raw === 'npm' ? 'npm' : undefined\n          })()\n          const settings = loadSettings(profile)\n          // 界面语言（客户端随请求携带）：错误消息按用户当前语言提示。\n          // 服务端只有中文/英文两套文案，除 zh 以外的语言（en、pt…）一律给英文。\n          const lang = typeof body === 'object' && body !== null && (body as { lang?: unknown }).lang === 'zh'\n            ? 'zh'\n            : 'en'\n          // 代理规则与诊断/安装通道一致：设置里的代理 → 系统代理 → 环境变量 → 直连。\n          const effectiveProxy = settings.proxy !== ''\n            ? settings.proxy\n            : (systemProxy() ?? process.env.HTTPS_PROXY ?? process.env.https_proxy ?? '')\n          // 安装用的 npm 源：设置里显式选择优先；未配置时读本机 npm 配置（与诊断同一套规则）。\n          // 只有公共源允许失败后换源；自定义/内网源保持单一候选，避免私有包名泄露给公共源。\n          const registries = registryCandidates(\n            settings.npmRegistry,\n            settings.npmRegistry === '' ? userNpmRegistry(profileDirectory(profile)) : '',\n            settings.registryFallback,\n          )\n          // 全局 npm 安装（`npm install -g <pkgs>`）：不进任何 profile、无需宿主重启。\n          // 包列表优先取 body.globalNpm，取不到时再从 rawRepo 解析，保证直接调 API 传完整命令也能识别。\n          const bodyGlobalNpm = Array.isArray((body as { globalNpm?: unknown }).globalNpm)\n            ? (body as { globalNpm: unknown[] }).globalNpm.filter((x): x is string => typeof x === 'string' && x !== '')\n            : []\n          const globalNpm: string[] = bodyGlobalNpm.length > 0 ? bodyGlobalNpm : (globalNpmPackagesOf(rawRepo) ?? [])\n          if (globalNpm.length > 0) {\n            // 包名逐个按 npm 包名语法校验 + 拒绝以 - 开头的 token（npm 会把 --xxx 当参数而非包名），数量封顶防滥用\n            if (globalNpm.length > 20 || globalNpm.some((p) => !validPackageName(p) || p.startsWith('-'))) {\n              sendJson(response, 400, { error: 'unsupported install target' })\n              return\n            }\n            // 通道校验与安装通道同构：全局安装本质是 npm 操作，吃「启用 NPM 安装」开关\n            if (source !== 'catalog' && !settings.enableNpmInstall) {\n              sendJson(response, 403, { error: 'npm installs are disabled by the security settings' })\n              return\n            }\n            // 队列级去重：同一包列表已在排队/执行中时拒绝\n            const identity = globalNpm.join(' ')\n            if (hasQueuedTarget(identity)) {\n              sendJson(response, 409, { error: `already queued: ${identity}` })\n              return\n            }\n            const task = startPluginMutation({\n              action: 'add',\n              profile,\n              target: identity,\n              displayTarget: identity,\n              globalNpm,\n              timeoutMs: COMMAND_TIMEOUT_MS,\n              env: mutationEnv(settings),\n              // 候选源（首选在前）：任务内遇到传输层失败时按顺序换源重试\n              registries,\n              // 全局 npm 安装由 NPM 包卡片/官方命令发起：日志体现入口渠道\n              installChannel: installChannel ?? 'npm',\n            })\n            sendJson(response, 200, { ok: true, task: task.id })\n            return\n          }\n          // 自定义安装目标只接受 npm 包名（@scope/name 或 name）。\n          if (!validPackageName(rawRepo)) {\n            sendJson(response, 400, { error: 'unsupported install target: expected an npm package name' })\n            return\n          }\n          const target = rawRepo\n          // 锁定精确版本（Hub 自我更新）：最新版可能仍在 pnpm 发布冷却期内，\n          // 客户端提示的是「已过冷却期」的版本，服务端必须按该版本安装而不是 @latest。\n          const pinVersion = typeof (body as { version?: unknown }).version === 'string'\n            ? (body as { version: string }).version.trim()\n            : ''\n          if (pinVersion !== '' && !/^\\d+\\.\\d+\\.\\d+(?:-[0-9A-Za-z.]+)?$/.test(pinVersion)) {\n            sendJson(response, 400, { error: 'invalid version' })\n            return\n          }\n          // 已尝试的安装方式（供失败提 Issue 预填）：保持为空\n          const attempts: string[] = []\n          // 目录插件安装：目录数据可能滞后于打包拆分，确认目录下发的 npm 目标确为该仓库的 DSH 包，\n          // 命中则记录 repo → 包名映射，客户端据此把依赖 key 匹配回仓库、列表立即显示「已安装」。\n          const catalogRepo = source === 'catalog' ? githubRepoOf(displayRepo) : null\n          if (catalogRepo !== null) {\n            const catalogTargetIsDsh = await isDshNpmPackageForRepo(rawRepo, catalogRepo, settings.npmRegistry, effectiveProxy, pinVersion)\n            if (catalogTargetIsDsh) recordResolvedNpmPackage(profile, catalogRepo, rawRepo)\n          }\n          // 命令行安装（目录外）受「启用 NPM 安装」开关控制；目录插件安装走目录白名单，不受开关影响。\n          if (source !== 'catalog' && !settings.enableNpmInstall) {\n            sendJson(response, 403, { error: 'npm installs are disabled by the security settings' })\n            return\n          }\n          // 命中已安装目标时按「更新」执行（pnpm add 对已存在依赖即原位覆盖重装）：\n          // 客户端已装列表可能与服务端不同步，覆盖重装比报错更友好且终态一致。\n          const installed = readInstalled(profile)\n          const already = installed[target] !== undefined ? target : null\n          if (already !== null) mode = 'update'\n          // 队列级去重：同一目标已在排队/执行中时拒绝，避免客户端防重竞态导致重复入队\n          if (hasQueuedTarget(target)) {\n            sendJson(response, 409, { error: `already queued: ${target}` })\n            return\n          }\n          // 安装前网络探测：探 registry 根而非具体包（404 是「包不存在」而非网络不通）；仅新安装执行，更新跳过。\n          // 首选源不通时按候选顺序继续探下一个，能通的那个提到首位供实际安装使用。\n          // 全部不通则 400 拦下并打 [network] 标记，客户端据此提示网络问题，而非插件问题。\n          let ordered = registries\n          if (already === null) {\n            const tried: string[] = []\n            let chosen: string | null = null\n            for (const candidate of registries) {\n              tried.push(candidate)\n              const net = await probeUrl(`${candidate}/`, effectiveProxy, 6000)\n              if (net.ok) {\n                chosen = candidate\n                break\n              }\n            }\n            if (chosen === null) {\n              // 错误消息按界面语言输出，让用户看清是网络问题而非插件问题\n              const hosts = tried.map(registryHost).join(' → ')\n              const error = lang === 'zh'\n                ? `[network] 安装已中止：安装前无法连接到 npm 源（${hosts}）—— 您的网络似乎不通或被拦截（断网 / DNS 解析失败 / 防火墙 / 代理配置问题）。这不是插件本身的问题，请检查网络连接或代理设置，运行「系统诊断」检测各通道连通性后重试。`\n                : `[network] install aborted: cannot reach the npm registry (${hosts}) before install — your network connection appears to be down or blocked (DNS / proxy / firewall). This is not a problem with the plugin itself. Check your connection or proxy settings, run the connectivity diagnostic, then retry.`\n              sendJson(response, 400, { error, attempts })\n              return\n            }\n            ordered = [chosen, ...registries.filter((r) => r !== chosen)]\n          }\n          // 新安装锁定「已过发布冷却期」的最高稳定版：pnpm 对发布还不满 24 小时的版本会不提示地回退，\n          // 锁定后装到的就是预期版本。更新已有目标时客户端已按冷却期筛选，继续走 @latest。\n          let installSpec = pinVersion !== '' ? `${target}@${pinVersion}` : undefined\n          if (installSpec === undefined && already === null) {\n            // 解析源与安装首选源一致，锁定的版本一定存在于真正会用的那个源；解析失败则不锁定，不阻断安装。\n            // 超时 5s：网络刚探测通过，卡住时也不能把安装请求拖到默认的 8s\n            const release = await lookupReleaseAge(target, ordered[0] ?? '', effectiveProxy, 5000)\n            if (release !== null && release.installable !== null) installSpec = `${target}@${release.installable.version}`\n          }\n          // 入队前复检：网络探测的 await 期间并发请求可能已通过上方检查，而此处到 startPluginMutation\n          // 之间无 await，JS 单线程保证同一目标至多一个任务，杜绝双击/并发双任务。\n          if (hasQueuedTarget(target)) {\n            sendJson(response, 409, { error: `already queued: ${target}` })\n            return\n          }\n          // 后台启动 CLI；客户端轮询 /status 获取进度\n          const task = startPluginMutation({\n            // mode=update（已安装目标的覆盖更新）以 update 动作入队：\n            // 日志按 update 类别写入磁盘（update.start/done/fail），实际 CLI 执行仍是 add <target>@latest\n            action: mode === 'update' ? 'update' : 'add',\n            profile,\n            target,\n            // npm 安装时 target 是包名：displayTarget 固定展示仓库名，待重启行/前端恢复不因安装目标形态而变\n            displayTarget: githubRepoOf(displayRepo) ?? undefined,\n            // 覆盖更新：npm 命令显式 @latest（pnpm add 无版本对已存在依赖是幂等的，不加版本不会真更新）\n            updateNpm: mode === 'update',\n            // 运行中 loader：安装成功后把新插件热加载进 loader，非桌面端 + 纯服务端插件无需重启即生效\n            loader,\n            timeoutMs: COMMAND_TIMEOUT_MS,\n            env: mutationEnv(settings),\n            // 候选源（首选在前）：任务内遇到传输层失败时按顺序换源重试\n            registries: ordered,\n            installSpec,\n            // 自定义安装入口渠道：日志/报错据此溯源\n            installChannel,\n          })\n          sendJson(response, 200, { ok: true, task: task.id })\n        } catch (error) {\n          sendJson(response, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/dsh-plugin-hub/uninstall',\n      handler: async (request, response) => {\n        if (!requireTrustedPost(request, response)) return\n        // 与安装一致：卸载也进入同一队列，FIFO 串行执行\n        try {\n          const body = await readJsonBody(request)\n          const name = typeof body === 'object' && body !== null && typeof (body as { name?: unknown }).name === 'string'\n            ? (body as { name: string }).name\n            : ''\n          // 展示用的 owner/repo：卸载命令只需要 npm 包名，但待重启行要与安装行一致地显示仓库名\n          const repo = typeof body === 'object' && body !== null && typeof (body as { repo?: unknown }).repo === 'string'\n            ? (body as { repo: string }).repo\n            : ''\n          if (!validPackageName(name) || name === 'dsh-plugin') {\n            sendJson(response, 400, { error: 'plugin cannot be uninstalled here' })\n            return\n          }\n          if (readInstalled(profile)[name] === undefined) {\n            sendJson(response, 400, { error: 'plugin is not installed' })\n            return\n          }\n          // 队列级去重：同一包已在排队/执行中卸载时拒绝\n          if (hasQueuedTarget(name)) {\n            sendJson(response, 409, { error: `already queued: ${name}` })\n            return\n          }\n          const task = startPluginMutation({\n            action: 'remove',\n            profile,\n            target: name,\n            // 卸载的 mutation 目标是 npm 包名；待重启行要显示 owner/repo（与安装行一致），非法/缺失时回退包名\n            displayTarget: githubRepoOf(repo) ?? undefined,\n            // 运行中 loader：卸载成功后主动移除条目，立即生效、无需重启\n            loader,\n            timeoutMs: COMMAND_TIMEOUT_MS,\n            env: mutationEnv(loadSettings(profile)),\n          })\n          sendJson(response, 200, { ok: true, task: task.id })\n        } catch (error) {\n          sendJson(response, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n  ]\n}\n"
    },
    {
      "path": "src/server/http/shared.ts",
      "content": "/**\n * DSH Plugin Hub — the community plugin marketplace for DeepSeek Harness.\n * Website: https://dsh-plugin.org\n * GitHub: https://github.com/dshplugin/dsh-plugin-hub\n *\n * 共享 HTTP 工具：路由/服务类型、请求校验助手，以及守卫每个 POST 变更的同源校验。\n * 由本目录其它路由模块引入。\n */\nimport type { IncomingMessage, ServerResponse } from 'node:http'\n\n/**\n * 跨平台宿主重启脚本（以 `node -e` 运行，独立于宿主进程）。\n * 不用 `/bin/sh -c`：Windows 无 /bin/sh，且 lsof/nohup 仅 POSIX 存在。\n * 由 `spawn(runtimeExecPath(), ['-e', SCRIPT, port], { detached, stdio:'ignore' })` 孵化，\n * 宿主进程被 kill 后仍能完成「停旧 → 等端口释放 → 拉起新 dsh web」。\n * 端口探测不到监听进程时不再假装重启（记一行日志后退出，见脚本内注释）。\n */\nexport const HOST_RESTART_SCRIPT = String.raw`const C = require('node:child_process')\nconst F = require('node:fs')\nconst P = require('node:path')\nconst O = require('node:os')\nconst win = process.platform === 'win32'\nconst port = Number(process.argv[1])\n\nfunction findPids() {\n  if (win) {\n    const out = C.spawnSync('netstat', ['-ano', '-p', 'tcp'], { encoding: 'utf8' })\n    const found = []\n    for (const line of String(out.stdout || '').split(/\\r?\\n/)) {\n      if (!/LISTENING/i.test(line)) continue\n      const parts = line.trim().split(/\\s+/)\n      const addr = parts[1] || ''\n      if (!addr.endsWith(':' + port)) continue\n      const pid = parts[parts.length - 1]\n      if (pid && /\\d+/.test(pid)) found.push(pid)\n    }\n    return found\n  }\n  const out = C.spawnSync('lsof', ['-ti', 'tcp:' + port, '-sTCP:LISTEN'], { encoding: 'utf8' })\n  return String(out.stdout || '').split(/\\s+/).filter(Boolean)\n}\n\nconst targets = findPids()\n// 一个监听进程都没找到 = 端口探测本身就失败了（netstat 输出格式 / 本地化差异），\n// 旧宿主仍占着端口。此时再拉一个 dsh web 只会在日志里以 EADDRINUSE 无提示地退出，\n// 用户却看到「重启完成」——不制造这种假象，留一行可诊断的记录后退出。\nif (targets.length === 0) {\n  logLine('restart aborted: no listener found on port ' + port)\n  process.exit(0)\n}\n\nfor (const pid of targets) {\n  try {\n    if (win) C.spawnSync('taskkill', ['/pid', pid, '/t', '/f'])\n    else process.kill(Number(pid), 'SIGTERM')\n  } catch {}\n}\n\nlet tries = 0\n;(function waitForStop() {\n  if (findPids().length === 0 || ++tries > 20) return startHost()\n  setTimeout(waitForStop, 250)\n})()\n\nfunction logLine(msg) {\n  try {\n    const dir = P.join(O.homedir(), '.dsh', 'logs')\n    F.mkdirSync(dir, { recursive: true })\n    F.appendFileSync(P.join(dir, 'dsh-web-' + port + '.log'), '[' + new Date().toISOString() + '] ' + msg + '\\n')\n  } catch {}\n}\n\nfunction startHost() {\n  const dir = P.join(O.homedir(), '.dsh', 'logs')\n  F.mkdirSync(dir, { recursive: true })\n  const fd = F.openSync(P.join(dir, 'dsh-web-' + port + '.log'), 'a')\n  const child = C.spawn('dsh', ['web', '--port', String(port)], {\n    detached: true,\n    shell: win,\n    stdio: ['ignore', fd, fd],\n  })\n  child.unref()\n}`\n\n/**\n * 宿主是否由桌面应用壳托管（`ELECTRON_RUN_AS_NODE=1`：壳用 Electron 二进制以 Node 模式跑宿主）。\n * 桌面端的宿主归应用壳管，插件重启不了它，也不该去 kill —— 详见 /restart 路由。\n */\nexport function isDesktopHost(): boolean {\n  return process.env.ELECTRON_RUN_AS_NODE === '1'\n}\n\nexport interface WebRoute {\n  kind: 'exact'\n  path: string\n  handler: (request: IncomingMessage, response: ServerResponse) => void | Promise<void>\n}\n\n/** 本插件用到的宿主 web-server 服务子集。 */\nexport interface WebServerService {\n  register(route: WebRoute): () => void\n}\n\nexport const PROFILE_RE = /^[A-Za-z0-9_-]+$/\nconst BODY_LIMIT_BYTES = 4 * 1024\nexport const COMMAND_TIMEOUT_MS = 5 * 60 * 1000\n\n/** 目录/统计数据代理的本地缓存时长：1 小时内重复打开插件市场直接读盘，\n *  不重复走 curl 拉远程 —— 重启宿主后首次打开同样秒开（缓存跨重启存活）。 */\nexport const CATALOG_CACHE_TTL_MS = 60 * 60 * 1000\n\nexport function sendJson(response: ServerResponse, status: number, value: unknown): void {\n  response.writeHead(status, {\n    'cache-control': 'no-store',\n    'content-type': 'application/json; charset=utf-8',\n  })\n  response.end(JSON.stringify(value))\n}\n\n/** 本机回环主机名：`localhost` / `127.0.0.1` / `[::1]` 指向同一台机器的同一个端口，\n *  字符串不同但同源，必须按同一来源比较。 */\nconst LOOPBACK_HOSTNAMES = new Set(['localhost', '127.0.0.1', '[::1]'])\n\n/** 把 `host[:port]` 形式的 authority 归一化成 `loopback:端口` —— 三个回环别名\n *  映射成同一个身份，端口缺省按 http 的 80 补齐；非回环主机名、以及解析不出来的值\n *  都返回 null。 */\nfunction loopbackAuthority(authority: string): string | null {\n  try {\n    const parsed = new URL(`http://${authority}`)\n    if (!LOOPBACK_HOSTNAMES.has(parsed.hostname.toLowerCase())) return null\n    return `loopback:${parsed.port === '' ? '80' : parsed.port}`\n  } catch {\n    return null\n  }\n}\n\n/** POST 变更只接受来自本地 web server 来源或桌面宿主页面。转出供测试（tests/routes.test.ts）使用 ——\n *  来源校验就是全部的 CSRF 防御。 */\nexport function isSameOrigin(request: IncomingMessage): boolean {\n  // 服务只绑定本机回环地址：Host 不是回环（局域网 IP、被改写的域名）一律拒绝，\n  // 顺带挡掉 DNS rebinding（Host 是攻击者域名，即便解析到 127.0.0.1）。\n  const host = request.headers.host\n  const hostKey = host === undefined ? null : loopbackAuthority(host)\n  if (hostKey === null) return false\n  const origin = request.headers.origin\n  // 桌面端宿主把 `/dsh-plugin-hub/*` 转发给本地 http server 时可能不带 Origin 头，\n  // 此时所有 POST 都会被判成 untrusted origin。浏览器对 POST 请求\n  // 必定携带 Origin（含同源 POST 与跨站表单），能省略该头的只有本机原生客户端，\n  // 而它们本来就能伪造任意 Origin，因此放行不扩大 CSRF 面。\n  if (origin === undefined || origin === '') return true\n  try {\n    const url = new URL(origin)\n    // 桌面端（Electron 宿主）的页面跑在宿主自定义协议下，origin 形如 `dsh-app://app`，\n    // 与 Host（如 localhost:3081）必然不等，因此必须显式放行该协议，否则桌面端全部 POST\n    // 都会被判成 untrusted origin。该协议只有宿主自身能产生，外部网页无法把 Origin\n    // 伪造成 `dsh-app://…`，放行不扩大 CSRF 面。\n    if (url.protocol === 'dsh-app:') return true\n    // 按归一化后的「主机名:端口」比较：`localhost` / `127.0.0.1` / `[::1]` 不再互相拒绝，\n    // 端口仍然必须一致（另一个本机进程不能被当成同一来源）。\n    return loopbackAuthority(url.host) === hostKey\n  } catch {\n    return false\n  }\n}\n\nexport function requireMethod(request: IncomingMessage, response: ServerResponse, method: 'GET' | 'POST'): boolean {\n  if (request.method === method) return true\n  response.writeHead(405, { allow: method })\n  response.end()\n  return false\n}\n\nexport function requireTrustedPost(request: IncomingMessage, response: ServerResponse): boolean {\n  if (!requireMethod(request, response, 'POST')) return false\n  if (isSameOrigin(request)) return true\n  sendJson(response, 403, { error: 'untrusted origin' })\n  return false\n}\n\nexport async function readJsonBody(request: IncomingMessage): Promise<unknown> {\n  const chunks: Buffer[] = []\n  let size = 0\n  for await (const chunk of request) {\n    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)\n    size += buffer.length\n    if (size > BODY_LIMIT_BYTES) throw new Error('request body too large')\n    chunks.push(buffer)\n  }\n  return JSON.parse(Buffer.concat(chunks).toString('utf8'))\n}\n"
